package br.edu.ifms.robotica.util;
import java.io.InputStream;import java.util.Properties;import javax.mail.*;import javax.mail.internet.*;
public class EmailService{private final Properties cfg=new Properties();public EmailService(){try(InputStream in=getClass().getClassLoader().getResourceAsStream("email.properties")){if(in!=null)cfg.load(in);}catch(Exception e){throw new IllegalStateException("Não foi possível carregar email.properties",e);}}
 public String baseUrl(){return valor("APP_BASE_URL","app.baseUrl","http://localhost:8080/portal-robotica");}
 public void enviarRedefinicao(String destino,String link)throws MessagingException{String host=valor("MAIL_HOST","mail.host",null),usuario=valor("MAIL_USERNAME","mail.username",null),senha=valor("MAIL_PASSWORD","mail.password",null);if(host==null||usuario==null||senha==null)throw new MessagingException("SMTP de teste não configurado.");Properties p=new Properties();p.put("mail.smtp.host",host);p.put("mail.smtp.port",valor("MAIL_PORT","mail.port","587"));p.put("mail.smtp.auth","true");p.put("mail.smtp.starttls.enable",valor("MAIL_STARTTLS","mail.starttls","true"));Session s=Session.getInstance(p,new Authenticator(){protected PasswordAuthentication getPasswordAuthentication(){return new PasswordAuthentication(usuario,senha);}});Message m=new MimeMessage(s);m.setFrom(new InternetAddress(valor("MAIL_FROM","mail.from","nao-responda@portal-robotica.local")));m.setRecipients(Message.RecipientType.TO,InternetAddress.parse(destino));m.setSubject("Redefinição de senha - Portal de Robótica");m.setText("Use o link abaixo em até 30 minutos:\n\n"+link+"\n\nSe você não solicitou, ignore esta mensagem.");Transport.send(m);}
 private String valor(String env,String key,String padrao){String v=System.getenv(env);if(v==null||v.isBlank())v=cfg.getProperty(key);return v==null||v.isBlank()?padrao:v.trim();}}
